import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"', strict=False))
    records = [row for row in records if row and any(cell.strip() for cell in row)]

    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    number_pattern = re.compile(
        r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$"
    )

    def is_number(value):
        return bool(number_pattern.fullmatch(value.strip()))

    candidates = []
    for index, row in enumerate(records):
        if len(row) != expected_width:
            continue
        text_count = sum(not is_number(cell) for cell in row)
        if not text_count:
            continue
        following = records[index + 1:index + 6]
        numeric_rows = [
            sum(is_number(cell) for cell in later) / max(1, len(later))
            for later in following
        ]
        data_score = sum(numeric_rows) / len(numeric_rows) if numeric_rows else 0
        candidates.append((data_score, text_count, -index, index))

    if candidates:
        header_index = max(candidates)[-1]
    else:
        header_index = next(
            (i for i, row in enumerate(records) if len(row) >= expected_width),
            0,
        )

    header = records[header_index]
    columns = header[:expected_width]
    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))

    rows = []
    for record in records[header_index + 1:]:
        if len(record) > expected_width:
            record = record[:expected_width - 1] + [";".join(record[expected_width - 1:])]
        elif len(record) < expected_width:
            record = record + [""] * (expected_width - len(record))
        rows.append(record)

    return {"columns": columns, "rows": rows}
